"""Bundled audio preset data encoded in compressed base64 for 100% WASM compatibility."""

import base64
import gzip

_PRESETS_B64_GZ: dict[str, str] = {
    "jazz_vibes": "",
    "classical_strings": "",
    "drums_beat": "",
    "speech_voice": "",
    "solo_trumpet": "",
}

def get_preset_bytes(key: str) -> bytes | None:
    """Decompresses and returns raw WAV audio bytes for the given preset key."""
    if key in _PRESETS_B64_GZ:
        return gzip.decompress(base64.b64decode(_PRESETS_B64_GZ[key]))
    return None
